            "- [ ] 所有设定可溯源，无\"存疑/未决\"项混入设定文件（conflicts.md 中标注状态的未决项除外）；孤证均已补证或降级标注",
            "- [ ] 产出文件中每条素材均可溯源至 `_溯源/<slug>/` 缓存文件，无仅凭对话记忆还原、缓存中查无出处的素材",
            "- [ ] 交付目录纯净：`<产出根目录>/<slug>/` 内除 10 个设定文件与 `assets/` 外无任何工作文件（草稿、原始素材、临时文件）",
            "- [ ] 溯源目录未入库：`_溯源/` 已写入宿主忽略配置（或已向用户明示请勿提交），且未被宿主构建/发布脚本扫描进交付物",
            "- [ ] 例句、台词、单方面评价等强素材全部来自原始素材，无一条 AI 自创；素材不足处已如实标注",
