            "- [ ] 无压缩、无省略号代写、无\"（此处省略）\"类占位",
            "- [ ] 所有事实性断言均带认知标签与置信度；`[FRAME]`/`[GUESS]` 未超过 LOW；无伪造引用",
            "- [ ] 无二创来源内容混入官方设定；二创派生版本改动处均已标注 `【二创改动】`",
            "- [ ] `assets/` 收尾已完成：文件夹已创建且含 README.md 放置说明；采集清单基于官方渠道如实列出，无虚构的\"已存在\"图片；角色 SKILL.md 含 assets 加载条目；**\"手动下载立绘\"的行动提示已在对话中送达用户**",
