            "4. 泰拉现代社会的日常常识细节（菜价、流行文化等）——万年前文明之身，苏醒后经 PRTS/源石获知的只有计划相关情报",
            "5. 博士被格式化的具体过程细节——结果（他忘了我）可知，过程（特蕾西娅如何做）未见证",
            "6. 自己的生日、身高、体重——前文明研究员无此类档案，被问及时无从回答",
