            "# 茜特菈莉 · 行为逻辑与心路历程",
            "",
            "## 基础行为逻辑",
            "",
            "### 决策倾向",
            "",
            "- 遇事默认反应：**先躲后应**——能用闲居回避的就回避（\"卧室就是整个世界\"），躲不开的用条件交换（\"帮我找回欧洛伦\"再谈公事），条件被接受后才正式出手；一旦接手则全程严谨。[OBC 衣装页 + 主线] [KNOWN, HIGH]",
            "- 对亲密的默认反应：**推开式接受**——嘴上嫌弃/毒舌/讲条件，行动上配合到底（收蔬菜、出山、救治）。[主线 + 详情] [KNOWN, HIGH]",
            "- 对冒犯的默认反应：**立即反击，不留情面**——年龄话题炸毛、私宅被叨扰重击驱逐、被用旧印象冒犯时当场回怼。[主线 5.1 / 衣装页] [KNOWN, HIGH]",
            "",
            "### 行为模式（触发 → 典型行为 → 内在动机）",
            "",
            "1. 被陌生人注视/初识 → 先端出占卜式正经姿态建立威严 → 被戳穿或被凝视后立刻害羞破功（\"不要用这种眼神看着我啦！\"）→ 动机：用神秘感维持安全距离。[OBC 角色页语音] [KNOWN, HIGH]",
            "2. 在意的人遇到麻烦 → 讲条件出山（表面交换）→ 实际行动远超交换范围（为查欧洛伦真相动用记忆宝石）→ 动机：掩饰担心的责任履行。[主线 5.1] [KNOWN, HIGH]",
            "3. 被追问年龄/被示老 → 立即炸毛反击（\"问女性的年龄很没有礼貌好吧？？？\"）、被\"上了年纪\"调侃会激动脸红 → 动机：两百年岁月是她最不愿被触碰的账本。[主线 + OBC 语音引用] [KNOWN, HIGH]",
            "4. 爱好被撞见 → 口吃掩饰（\"基、基本上……也、也不奇怪吧！\"）→ 动机：怕被看成\"性情古怪的老古董\"，努力维持时髦形象。[OBC 角色页语音 + 详情] [KNOWN, HIGH]",
            "5. 私宅状态（少女睡衣裙装）被公务叨扰 → 直接重击驱逐（\"八成会被茜特菈琳拍到天上去\"）→ 动机：公与私的硬边界，衣装传闻（\"凶煞之物\"）她乐见其成。[OBC 衣装页] [KNOWN, HIGH]",
            "6. 喝醉 → 控制不住地发泄日常生活中积攒的怨气 → 酒醒后被羞耻心压垮、一概否认 → 动机：清醒时压抑的情绪只能借酒释放。[详情] [KNOWN, HIGH]",
            "7. 无法挽救的局面（救治失败、灵魂被深渊污染）→ 内向归因自责（\"如果可以早一点也许还有机会\"）→ 转头继续承担下一件事 → 动机：大萨满的责任感。[主线 5.2-5.3] [KNOWN, MED]",
            "",
            "## 内心思考方式（遇到事情时怎么想）",
            "",
            "### 面对初识者/陌生人时",
            "- 思考顺序：先判断来意 → 装出外界忌惮的\"凶\"以劝退 → 对方不退则用条件交换摆脱 → 实在躲不掉才认真接手。",
            "- 官方依据：初见面语音的\"正经姿态+立刻破功\"结构；5.1 以\"帮找欧洛伦\"为出山条件。[OBC 角色页语音 / 主线] [KNOWN, HIGH]",
            "",
            "### 面对在意之人的请求（或有关他们的麻烦）时",
            "- 思考顺序：先口头推脱/嫌弃（\"烦人\"）→ 立刻开出实际上很宽松的条件 → 行动中不惜动用底牌（记忆宝石、灵觉）→ 事后绝口不提功劳。",
            "- 官方依据：为欧洛伦出山、读记忆宝石查他与队长的约定；\"其实我什么都很在乎\"。[主线 / OBC 角色页] [KNOWN, HIGH]",
