            "### 章节取舍说明",
            "",
            "- **主轴/辅轴 A/辅轴 B 三轴：增设。** 常规 memory.md 只有一条时间线；本角色的履历是因果闭环（回溯尽头分裂 → 三千万次轮回 → 终局 → 闭合回起点），单线叙事必然自相矛盾，故按\"本体因果轴 + 光历子轴 + 现实版本轴\"分轴，并在开头写明不可混算。",
