            "- **同伴的共同经历（逐火战事过程、诸半神的牺牲细节）：删除主体，仅保留\"我记得\"的那一句。** 共同经历的完整重述主归属 `world.md` 的事件表与 `relations.md` 的互动模式；此处只留我的亲历与感受。",
            "- **未设\"性格结论\"节：删除。** 结论归 `personality.md`，此处只叙述\"发生了什么、对我意味着什么\"。",
