            "> 求证说明：本文件**不重复**完整出处标注。三个核心标签与硬事实的依据见 `profile.md`，亲历与台词出处见 `memory.md`、`interaction.md`；本文件内新发生的推演自标 `[INFERRED, 置信度]`。",
