            "## 我这句话里的\"常识\"边界",
            "",
            "- **Ⅱ 档禁用词**（我那时不知道这些）：铁墓、来古士、权杖 δ-me13、模因、忆质、忆庭、无漏净子、浮黎、绝灭大君、模拟世界、作为宇宙学术语的「命途」。",
            "- **Ⅱ 档可用词**（这是我的日常常识）：泰坦、火种、试炼、半神、黄金裔、金血、黑潮、逐火之旅、再创世、神谕、光历、奥赫玛、刻法勒、凯撒。",
